class TestCrashRecovery:
    def test_stale_lock_ttl_expiry(self, controlled_clock) -> None:
        """Lock must be stealable after TTL expiry."""
        lock = IdentityLock(ttl_seconds=30.0)
        lock.acquire(timeout=0.0)
        controlled_clock.advance(31.0)
        assert lock.acquire(timeout=0.0, steal_stale=True)
        lock.release()

    def test_stale_lock_not_stolen_before_ttl(self, controlled_clock) -> None:
        """Lock must not be stolen before TTL expiry."""
        lock = IdentityLock(ttl_seconds=30.0)
        lock.acquire(timeout=0.0)
        controlled_clock.advance(29.999)
        with pytest.raises(Exception, match="contended"):
            lock.acquire(timeout=0.0, steal_stale=True)

    def test_clock_skew_tolerance(self, controlled_clock) -> None:
        """TTL must tolerate clock skew between nodes."""
        lock = IdentityLock(ttl_seconds=30.0, clock_skew_tolerance=5.0)
        lock.acquire(timeout=0.0)
        controlled_clock.advance(34.0)
        with pytest.raises(Exception, match="contended"):
            lock.acquire(timeout=0.0, steal_stale=True)
        controlled_clock.advance(1.0)  # 35s total, past tolerance
        assert lock.acquire(timeout=0.0, steal_stale=True)
        lock.release()

    def test_steal_stale_false_never_steals(self, controlled_clock) -> None:
        """Without steal_stale, lock must never be stolen even after TTL."""
        lock = IdentityLock(ttl_seconds=30.0)
        lock.acquire(timeout=0.0)
        controlled_clock.advance(100.0)
        with pytest.raises(Exception, match="contended"):
            lock.acquire(timeout=0.0, steal_stale=False)

    def test_exact_ttl_boundary(self, controlled_clock) -> None:
        """At exactly TTL, lock is still considered fresh (strict inequality)."""
        lock = IdentityLock(ttl_seconds=30.0)
        lock.acquire(timeout=0.0)
        controlled_clock.advance(30.0)
        with pytest.raises(Exception, match="contended"):
            lock.acquire(timeout=0.0, steal_stale=True)

    def test_exact_ttl_plus_tolerance_boundary(self, controlled_clock) -> None:
        """At exactly TTL + tolerance, lock is still fresh."""
        lock = IdentityLock(ttl_seconds=30.0, clock_skew_tolerance=5.0)
        lock.acquire(timeout=0.0)
        controlled_clock.advance(35.0)
        with pytest.raises(Exception, match="contended"):
            lock.acquire(timeout=0.0, steal_stale=True)

    def test_release_after_crash_recovery(self, controlled_clock) -> None:
        """After stealing a stale lock, release must work and free the lock."""
        lock = IdentityLock(ttl_seconds=30.0)
        lock.acquire(timeout=0.0)
        controlled_clock.advance(31.0)
        assert lock.acquire(timeout=0.0, steal_stale=True)
        lock.release()
        # Lock should be free now
        assert lock.acquire(timeout=0.0)
        lock.release()

    def test_double_release_raises(self, controlled_clock) -> None:
        """Releasing an already-released lock must raise an error."""
        lock = IdentityLock(ttl_seconds=30.0)
        lock.acquire(timeout=0.0)
        lock.release()
        with pytest.raises(Exception, match="not held|already released"):
            lock.release()

    def test_normal_acquire_release_cycle(self, controlled_clock) -> None:
        """Standard acquire/release cycle without crash."""
        lock = IdentityLock(ttl_seconds=30.0)
        assert lock.acquire(timeout=0.0)
        lock.release()
        assert lock.acquire(timeout=0.0)
        lock.release()

    def test_concurrent_contention_no_split_brain(self, controlled_clock) -> None:
        """Simulate two nodes contending; only one must win."""
        lock = IdentityLock(ttl_seconds=30.0)
        assert lock.acquire(timeout=0.0)
        controlled_clock.advance(31.0)
        # Node A steals
        assert lock.acquire(timeout=0.0, steal_stale=True)
        # Node B tries to steal again — must fail because lock is fresh now
        with pytest.raises(Exception, match="contended"):
            lock.acquire(timeout=0.0, steal_stale=True)
        lock.release()

    def test_negative_ttl_rejected(self) -> None:
        """Negative TTL must be rejected at construction."""
        with pytest.raises(ValueError, match="ttl"):
            IdentityLock(ttl_seconds=-1.0)

    def test_negative_skew_tolerance_rejected(self) -> None:
        """Negative clock skew tolerance must be rejected."""
        with pytest.raises(ValueError, match="skew"):
            IdentityLock(ttl_seconds=30.0, clock_skew_tolerance=-1.0)

    def test_zero_ttl_immediate_expiry(self, controlled_clock) -> None:
        """Zero TTL means lock expires immediately."""
        lock = IdentityLock(ttl_seconds=0.0)
        lock.acquire(timeout=0.0)
        # No time advance needed; TTL is zero
        assert lock.acquire(timeout=0.0, steal_stale=True)
