class TestCrashRecoveryProperties:
    @given(
        ttl=st.floats(min_value=0.1, max_value=100.0),
        advance=st.floats(min_value=0.0, max_value=200.0),
        skew=st.floats(min_value=0.0, max_value=20.0),
    )
    @settings(max_examples=100)
    def test_ttl_expiry_property(self, controlled_clock, ttl, advance, skew) -> None:
        """Property: lock is stealable iff advance > ttl + skew."""
        lock = IdentityLock(ttl_seconds=ttl, clock_skew_tolerance=skew)
        lock.acquire(timeout=0.0)
        controlled_clock.advance(advance)
        if advance > ttl + skew:
            assert lock.acquire(timeout=0.0, steal_stale=True)
            lock.release()
        else:
            with pytest.raises(Exception, match="contended"):
                lock.acquire(timeout=0.0, steal_stale=True)

    @given(
        ttl=st.floats(min_value=0.1, max_value=50.0),
        steps=st.lists(st.floats(min_value=0.0, max_value=10.0), min_size=1, max_size=10),
    )
    @settings(max_examples=50)
    def test_incremental_clock_advance(self, controlled_clock, ttl, steps) -> None:
        """Property: cumulative advance determines stealability."""
        lock = IdentityLock(ttl_seconds=ttl)
        lock.acquire(timeout=0.0)
        total_advance = 0.0
        for step in steps:
            controlled_clock.advance(step)
            total_advance += step
        if total_advance > ttl:
            assert lock.acquire(timeout=0.0, steal_stale=True)
            lock.release()
        else:
            with pytest.raises(Exception, match="contended"):
                lock.acquire(timeout=0.0, steal_stale=True)


