# Chaos / Stress Tests
# ---------------------------------------------------------------------------
class TestCrashRecoveryChaos:
    def test_rapid_acquire_release_cycles(self, controlled_clock) -> None:
        """Stress test: 1000 acquire/release cycles with no crash."""
        lock = IdentityLock(ttl_seconds=30.0)
        for _ in range(1000):
            assert lock.acquire(timeout=0.0)
            lock.release()
        # Final state: lock is free
        assert lock.acquire(timeout=0.0)
        lock.release()

    def test_rapid_steal_cycles(self, controlled_clock) -> None:
        """Stress test: 100 steal cycles after TTL expiry."""
        lock = IdentityLock(ttl_seconds=0.1)
        for _ in range(100):
            lock.acquire(timeout=0.0)
            controlled_clock.advance(0.2)
            assert lock.acquire(timeout=0.0, steal_stale=True)
            lock.release()

    def test_lock_state_after_process_signal(self, controlled_clock, tmp_path) -> None:
        """Simulate owner crash via SIGKILL and verify lock recovery."""
        lock_file = tmp_path / "test.lock"
        lock = IdentityLock(ttl_seconds=30.0, lock_file=lock_file)
        lock.acquire(timeout=0.0)
        # Simulate crash: write stale PID and advance clock
        controlled_clock.advance(31.0)
        # New process acquires with steal
        assert lock.acquire(timeout=0.0, steal_stale=True)
        lock.release()
        # Verify lock file is cleaned up
        assert not lock_file.exists() or lock_file.read_text() == ""


